using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Threading;using System.Threading.Tasks;
public class CodexWakeConfig {
 public bool Enabled,FiveHour;public bool Weekly=true;public List<string> Attempts=new List<string>();public string LastResult="尚未尝试自动唤醒";public DateTime AttemptedUtc;
 public string CandidateAccount="";public DateTime CandidateCheckedUtc;public List<string> CandidateKeys=new List<string>();[ScriptIgnore]public bool Changed;
 public string Reserve(CodexQuotaSnapshot s,CodexQuotaSnapshot previous,DateTime now){
  Changed=false;if(!Enabled||s==null||previous==null||s.RequiresAuthorization||String.IsNullOrEmpty(s.AccountKey)||s.AccountKey!=previous.AccountKey||String.IsNullOrEmpty(s.PlanType)||s.CheckedUtc<=previous.CheckedUtc||now<s.CheckedUtc||now-s.CheckedUtc>TimeSpan.FromMinutes(2))return null;
  if(Attempts==null)Attempts=new List<string>();if(CandidateKeys==null)CandidateKeys=new List<string>();
  if(CandidateKeys.Count>0){bool valid=CandidateAccount==s.AccountKey&&s.CheckedUtc>=CandidateCheckedUtc&&s.CheckedUtc-CandidateCheckedUtc<=TimeSpan.FromMinutes(10)&&CandidateKeys.All(key=>s.Windows.Any(w=>key.StartsWith(s.AccountKey+":"+w.Minutes+":")&&w.PendingStart(now)&&(w.Minutes==300?FiveHour:Weekly)));if(valid&&s.CheckedUtc-CandidateCheckedUtc<TimeSpan.FromSeconds(30))return null;if(valid){var keys=CandidateKeys.Where(k=>!Attempts.Contains(k)).ToArray();Attempts.AddRange(keys);Attempts=Attempts.Skip(Math.Max(0,Attempts.Count-100)).ToList();CandidateKeys.Clear();AttemptedUtc=now;LastResult="两次官方核验额度已恢复；已记录本周期唯一尝试";Changed=true;return keys.Length==0?null:String.Join("|",keys);}CandidateKeys.Clear();Changed=true;}
  var pending=new List<string>();foreach(var w in s.Windows){if(w.Minutes==300&&!FiveHour||w.Minutes==10080&&!Weekly||!w.PendingStart(now))continue;var old=previous.Windows.FirstOrDefault(x=>x.Minutes==w.Minutes);if(old==null||old.ResetUtc==default(DateTime)||old.PendingStart(previous.CheckedUtc))continue;string key=s.AccountKey+":"+w.Minutes+":"+old.ResetUtc.Ticks;if(!Attempts.Contains(key))pending.Add(key);}
  if(pending.Count>0){CandidateKeys=pending;CandidateAccount=s.AccountKey;CandidateCheckedUtc=s.CheckedUtc;LastResult="首次核验额度恢复，等待下一次官方核验后再尝试";Changed=true;}return null;
 }

}
public sealed partial class CodexQuotaReader {
 int waking;
 internal static string AccountPlan(object result){var root=result as Dictionary<string,object>;object value;var account=root!=null&&root.TryGetValue("account",out value)?value as Dictionary<string,object>:null;object type,plan;if(account==null||!account.TryGetValue("type",out type)||Convert.ToString(type)!="chatgpt")return "";return account.TryGetValue("planType",out plan)?Convert.ToString(plan):"";}
 public void MaybeWake(CodexQuotaSnapshot s,CodexQuotaConfig cfg,DateTime now,Action persist){
  if(!cfg.Enabled||!cfg.BackgroundRefresh||Environment.GetEnvironmentVariable("CONAN_PET_TEST_MODE")=="1"||Interlocked.CompareExchange(ref waking,1,0)!=0)return;
  string reservation=null;try{reservation=cfg.Wake.Reserve(s,cfg.LastObserved,now);if(cfg.Wake.Changed)persist();if(reservation==null){Interlocked.Exchange(ref waking,0);return;}}catch{Interlocked.Exchange(ref waking,0);throw;}
  string account=s.AccountKey,exe=cfg.Executable,home=cfg.Home;
  Task.Run(()=>{string result;try{if(!cfg.Wake.Enabled)result="开关已关闭，已取消本次尝试";else if(Trust==null)result="额度程序未授权，本次未发送";else using(var permit=Trust.OpenVerified(exe,home)){var verified=Fetch(permit.Identity.Executable,permit.Identity.Home);if(verified.AccountKey!=account||String.IsNullOrEmpty(verified.PlanType))throw new IOException("账户已变化或不是ChatGPT订阅登录，本次未发送");if(!verified.Windows.Any(w=>w.PendingStart(DateTime.UtcNow)))result="周期已由其他请求启动，无需唤醒";else {var model=LightModel(permit.Identity.Executable,permit.Identity.Home);if(!cfg.Wake.Enabled)result="开关已关闭，本次未发送";else result=RunMinimalRequest(permit.Identity.Executable,permit.Identity.Home,model.Item1,model.Item2);}}}catch(Exception e){result="本次唤醒未完成（"+e.GetType().Name+"），不会自动重试；可查看官方额度状态。";}lock(gate){cfg.Wake.LastResult=result;Dirty=true;}RefreshNow();Interlocked.Exchange(ref waking,0);});
 }
 internal static Tuple<string,string> LightModel(string exe,string home){
  var info=new ProcessStartInfo(exe,"app-server"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["CODEX_HOME"]=home;
  using(var p=Process.Start(info)){try{p.StandardError.ReadToEndAsync();var json=new JavaScriptSerializer();Action<object> send=value=>{p.StandardInput.WriteLine(json.Serialize(value));p.StandardInput.Flush();};send(new{id=1,method="initialize",@params=new{clientInfo=new{name="conan-quota-models",version="5.30.0"}}});var until=DateTime.UtcNow.AddSeconds(15);while(DateTime.UtcNow<until){var read=p.StandardOutput.ReadLineAsync();if(!read.Wait(Math.Max(1,(int)(until-DateTime.UtcNow).TotalMilliseconds))||read.Result==null)break;var d=json.Deserialize<Dictionary<string,object>>(read.Result);object id;if(!d.TryGetValue("id",out id))continue;if(d.ContainsKey("error"))throw new IOException("模型列表不可用");if(Convert.ToInt32(id)==1){send(new{method="initialized",@params=new{}});send(new{id=2,method="model/list",@params=new{limit=100}});}else if(Convert.ToInt32(id)==2){var r=(Dictionary<string,object>)d["result"];var data=(System.Collections.IEnumerable)r["data"];foreach(Dictionary<string,object> model in data){string name=Convert.ToString(model["model"]);object hidden;if(model.TryGetValue("hidden",out hidden)&&Convert.ToBoolean(hidden))continue;if(!name.Contains("mini")&&!name.Contains("luna"))continue;string effort=null;object options;if(model.TryGetValue("supportedReasoningEfforts",out options))foreach(Dictionary<string,object> option in (System.Collections.IEnumerable)options){string e=Convert.ToString(option["reasoningEffort"]);if(e=="none"||e=="minimal"||e=="low"){effort=e;break;}}if(effort!=null)return Tuple.Create(name,effort);}throw new IOException("没有可用的轻量模型，已跳过；不会回退到高成本模型");}}throw new IOException("读取模型列表超时");}finally{if(!p.HasExited)p.Kill();}}
 }
 internal static string MinimalArguments(string model,string effort,string directory){
  if(String.IsNullOrEmpty(model)||model.Any(c=>!Char.IsLetterOrDigit(c)&&c!='-'&&c!='.'&&c!='_')||!new[]{"none","minimal","low"}.Contains(effort))throw new ArgumentException("无效的轻量模型参数");
  return "exec --ignore-user-config --ignore-rules --ephemeral --skip-git-repo-check --sandbox read-only --model "+model+" -c approval_policy=\"never\" -c web_search=\"disabled\" -c model_reasoning_effort=\""+effort+"\" -c model_reasoning_summary=\"none\" -c notify=[] -c model_providers.openai.request_max_retries=0 -c model_providers.openai.stream_max_retries=0 --disable unbounded_connection_retries -c project_doc_max_bytes=0 --disable shell_tool --disable unified_exec --disable plugins --disable apps --disable hooks --disable multi_agent --disable browser_use --disable computer_use --disable image_generation --disable code_mode --disable code_mode_host --disable view_image --cd \""+directory+"\" \"Reply only OK. Do not use tools.\"";
 }
 static string RunMinimalRequest(string exe,string home,string model,string effort){
  string directory=Path.Combine(Path.GetTempPath(),"conan-quota-wake-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);
  try{var info=new ProcessStartInfo(exe,MinimalArguments(model,effort,directory)){WorkingDirectory=directory,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["CODEX_HOME"]=home;foreach(string name in new[]{"OPENAI_API_KEY","OPENAI_BASE_URL","AZURE_OPENAI_API_KEY","CODEX_API_KEY"})info.EnvironmentVariables.Remove(name);
   using(var p=Process.Start(info)){p.StandardInput.Close();p.StandardOutput.ReadToEndAsync();p.StandardError.ReadToEndAsync();if(!p.WaitForExit(45000)){p.Kill();return "最小请求超时，本周期不再自动尝试；请核对官方额度。";}return p.ExitCode==0?"已完成一次最小请求（"+model+"）；新周期以随后官方核验为准。":"最小请求未完成，本周期不再自动尝试。";}
  }finally{try{Directory.Delete(directory,true);}catch(IOException){}catch(UnauthorizedAccessException){}}
 }
}
